import React from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';

const Header = () => {
  const { user, logout } = useAuth();
  const navigate = useNavigate();

  const handleLogout = () => {
    logout();
    navigate('/login');
  };

  return (
    <header className="header">
      <div className="header-content">
        <Link to="/" className="logo">
          🏢 Réservation de Salles
        </Link>
        
        <nav className="nav-links">
          <Link to="/" className="nav-link">Accueil</Link>
          <Link to="/rooms" className="nav-link">Salles</Link>
          
          {user ? (
            <>
              {/* TOUS les utilisateurs connectés voient "Mon compte" */}
              <Link to="/dashboard" className="nav-link">Mon compte</Link>
              
              {/* SEULEMENT les propriétaires et admins voient "Espace Propriétaire" */}
              {(user.role === 'owner' || user.role === 'admin') && (
                <Link to="/owner/dashboard" className="nav-link">Espace Propriétaire</Link>
              )}
              
              {/* SEULEMENT les admins voient "Administration" */}
              {user.role === 'admin' && (
                <Link to="/admin/dashboard" className="nav-link">Administration</Link>
              )}
              
              <button onClick={handleLogout} className="btn btn-secondary">
                Déconnexion
              </button>
              <span className="user-greeting">Bonjour, {user.first_name}</span>
            </>
          ) : (
            <>
              <Link to="/login" className="nav-link">Connexion</Link>
              <Link to="/register" className="btn btn-primary">Inscription</Link>
            </>
          )}
        </nav>
      </div>
    </header>
  );
};

export default Header;
